raw:
{
  "summary": [
    {
      "text": "Математическая модель упругой фильтрации строится на сочетании закона сохранения массы, закона Дарси и уравнений состояния.",
      "claims": [
        "c1"
      ]
    },
    {
      "text": "В базовой модели проницаемость и вязкость считаются постоянными, хотя в реальности они могут меняться.",
      "claims": [
        "c2"
      ]
    }
  ],
  "how_it_works": [
    {
      "text": "Для вывода уравнений используются три компонента: уравнение неразрывности, закон Дарси и уравнения состояния.",
      "claims": [
        "c1"
      ]
    },
    {
      "text": "Уравнение неразрывности связывает изменение плотности и пористости с дивергенцией потока.",
      "claims": [
        "c3"
      ]
    },
    {
      "text": "Закон Дарси описывает скорость фильтрации через градиент давления и свойства среды.",
      "claims": [
        "c4"
      ]
    },
    {
      "text": "Плотность, пористость, проницаемость и вязкость зависят от давления.",
      "claims": [
        "c5"
      ]
    },
    {
      "text": "После пренебрежения массовыми силами вводится обобщенная функция Лейбензона.",
      "claims": [
        "c6"
      ]
    },
    {
      "text": "Функция Лейбензона позволяет записать уравнение в виде дифференциального уравнения теплопроводности.",
      "claims": [
        "c7"
      ]
    },
    {
      "text": "Уравнение состояния жидкости связывает плотность с давлением через коэффициент сжимаемости.",
      "claims": [
        "c8"
      ]
    },
    {
      "text": "Уравнение состояния среды связывает пористость с давлением через коэффициент упругости.",
      "claims": [
        "c9"
      ]
    },
    {
      "text": "В модели проницаемость и вязкость принимаются постоянными величинами.",
      "claims": [
        "c10"
      ]
    },
    {
      "text": "Лабораторные данные показывают, что проницаемость может меняться при деформациях.",
      "claims": [
        "c11"
      ]
    },
    {
      "text": "Учет зависимости проницаемости от пористости усложняет модель.",
      "claims": [
        "c12"
      ]
    }
  ],
  "steps": [
    {
      "text": "Записывается уравнение неразрывности для потока в пористой среде.",
      "claims": [
        "c3"
      ]
    },
    {
      "text": "Подставляется закон Дарси для определения скорости фильтрации.",
      "claims": [
        "c4"
      ]
    },
    {
      "text": "Вводятся уравнения состояния для плотности и пористости.",
      "claims": [
        "c8",
        "c9"
      ]
    },
    {
      "text": "Пренебрегаются массовыми силами и вводится функция Лейбензона.",
      "claims": [
        "c6"
      ]
    },
    {
      "text": "Получается итоговое дифференциальное уравнение фильтрации.",
      "claims": [
        "c7"
      ]
    }
  ],
  "examples": [],
  "numbers": [
    {
      "text": "При естественном упругом режиме добывается до 2–5% извлекаемых запасов.",
      "claims": [
        "c13"
      ]
    },
    {
      "text": "На месторождении Тенгиз при упругом режиме будет отобрано до 20% запасов нефти.",
      "claims": [
        "c14"
      ]
    }
  ],
  "formulas": [
    {
      "unit": "u478-04",
      "latex": "\\frac{\\partial m\\rho}{\\partial t} + \\text{div } \\rho\\bar{w} = 0",
      "vars": [
        {
          "sym": "m",
          "meaning": "пористость",
          "unit": "безразмерная"
        },
        {
          "sym": "\\rho",
          "meaning": "плотность жидкости",
          "unit": "кг/м³"
        },
        {
          "sym": "t",
          "meaning": "время",
          "unit": "с"
        },
        {
          "sym": "\\bar{w}",
          "meaning": "скорость фильтрации",
          "unit": "м/с"
        }
      ]
    },
    {
      "unit": "u478-05",
      "latex": "\\bar{w} = -\\frac{k}{\\mu}(\\text{grad } p + \\rho\\bar{f})",
      "vars": [
        {
          "sym": "k",
          "meaning": "проницаемость",
          "unit": "м²"
        },
        {
          "sym": "\\mu",
          "meaning": "вязкость",
          "unit": "Па·с"
        },
        {
          "sym": "p",
          "meaning": "давление",
          "unit": "Па"
        },
        {
          "sym": "\\bar{f}",
          "meaning": "массовая сила",
          "unit": "м/с²"
        }
      ]
    },
    {
      "unit": "u478-11",
      "latex": "P = \\int \\frac{k(p)}{\\mu(p)} \\rho(p) \\, dp",
      "vars": [
        {
          "sym": "P",
          "meaning": "функция Лейбензона",
          "unit": "Па·м²/с"
        },
        {
          "sym": "p",
          "meaning": "давление",
          "unit": "Па"
        }
      ]
    },
    {
      "unit": "u478-13",
      "latex": "\\rho = \\rho_0 [1 + \\beta_\\infty (p - p_0)]",
      "vars": [
        {
          "sym": "\\rho_0",
          "meaning": "плотность при начальном давлении",
          "unit": "кг/м³"
        },
        {
          "sym": "\\beta_\\infty",
          "meaning": "коэффициент сжимаемости жидкости",
          "unit": "1/Па"
        },
        {
          "sym": "p_0",
          "meaning": "начальное давление",
          "unit": "Па"
        }
      ]
    },
    {
      "unit": "u478-14",
      "latex": "m = m_0 + \\beta_c (p - p_0)",
      "vars": [
        {
          "sym": "m_0",
          "meaning": "пористость при начальном давлении",
          "unit": "безразмерная"
        },
        {
          "sym": "\\beta_c",
          "meaning": "коэффициент упругости породы",
          "unit": "1/Па"
        }
      ]
    }
  ],
  "misconception": {
    "wrong": "Модель пласта точно знает, что под землёй.",
    "right": [
      {
        "text": "Модель является упрощением: проницаемость и вязкость считаются постоянными, хотя в реальности они меняются.",
        "claims": [
          "c10",
          "c11"
        ]
      }
    ]
  }}
